def _slugify(text):
    text = text.lower()
    text = (text.replace("é", "e").replace("è", "e").replace("ê", "e")
                .replace("à", "a").replace("â", "a").replace("î", "i")
                .replace("ô", "o").replace("û", "u").replace("ç", "c")
                .replace("'", "-").replace('"', ""))
    text = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return text


